  {id:8,name:'Ko‘k choy',category:'Ichimliklar',desc:'Xushbo‘y ko‘k choy. Milliy dasturxonning ajralmas hamrohi.',price:10000,weight:'600 ml',photo:'photo-1544787219-7f47ccb76574',tag:''},
  {id:9,name:'Chuchvara',category:'Milliy taomlar',desc:'Qo‘lda tugilgan chuchvara, go‘shtli bulyon va qatiq.',price:38000,weight:'350 g',photo:'photo-1563245372-f21724e3856d',tag:''}
