let category='Barchasi';const cart=new Map();const money=n=>n.toLocaleString('uz-UZ');const $=s=>document.querySelector(s);
const cats=['Barchasi','Milliy taomlar','Kaboblar','Sho‘rvalar','Salatlar','Ichimliklar'];
$('#categories').innerHTML=cats.map((c,i)=>`<button class="${i===0?'active':''}" aria-pressed="${i===0}" data-category="${c}">${c}</button>`).join('');
function render(){const query=$('#search').value.trim().toLocaleLowerCase();const items=dishes.filter(d=>(category==='Barchasi'||d.category===category)&&(d.name+' '+d.desc).toLocaleLowerCase().includes(query));$('#result').textContent=`${items.length} ta taom va ichimlik`;$('#products').innerHTML=items.length?items.map(d=>`<article class="card"><div class="card-image"><img src="https://images.unsplash.com/${d.photo}?auto=format&fit=crop&w=650&q=80" alt="${d.name} uchun namunaviy surat" loading="lazy">${d.tag?`<span class="tag">${d.tag}</span>`:''}</div><div class="card-body"><div class="dish-meta">${d.category} · ${d.weight}</div><h3>${d.name}</h3><p>${d.desc}</p><div class="card-bottom"><span class="price">${money(d.price)} <small>so‘m</small></span><button class="add" data-add="${d.id}" aria-label="${d.name}ni tanlash">+</button></div></div></article>`).join(''):'<p class="empty">Taom topilmadi. Boshqa nom bilan qidirib ko‘ring.</p>';}
$('#categories').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});render();});$('#search').addEventListener('input',render);
let toastTimer;$('#products').addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(!b)return;const id=Number(b.dataset.add);cart.set(id,(cart.get(id)||0)+1);updateCart();$('#toast').textContent=`${dishes.find(d=>d.id===id).name} tanlovga qo‘shildi`;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2000);});
function updateCart(){let total=0,count=0;$('#cart-items').innerHTML=[...cart].map(([id,n])=>{const d=dishes.find(x=>x.id===id);total+=n*d.price;count+=n;return `<div class="cart-row"><div>${d.name}<small>${money(d.price*n)} so‘m</small></div><div class="quantity"><button data-change="${id}" data-step="-1" aria-label="${d.name} sonini kamaytirish">−</button><span>${n}</span><button data-change="${id}" data-step="1" aria-label="${d.name} sonini oshirish">+</button></div></div>`;}).join('')||'<p class="empty">Hozircha tanlovingiz bo‘sh.</p>';$('#count').textContent=count;$('#total').textContent=money(total)+' so‘m';}
$('#cart-items').addEventListener('click',e=>{const b=e.target.closest('[data-change]');if(!b)return;const id=Number(b.dataset.change),n=cart.get(id)+Number(b.dataset.step);if(n>0)cart.set(id,n);else cart.delete(id);updateCart();});$('#basket').addEventListener('click',()=>{$('#cart').showModal();});$('#close').addEventListener('click',()=>$('#cart').close());$('#cart').addEventListener('click',e=>{if(e.target===$('#cart')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});render();updateCart();
